/**
 * engine-server/pipeline/collaboration-collector.ts — 运行时协作事件采集（V1.2 第二阶段）
 *
 * 在 Protocol Engine 中间件的消息流上埋 6 缝隙维度计数器。
 * 用内存存储（轻量级，生产环境可替换为 SQLite/Redis），供 M3 进化引擎消费。
 *
 * 采集维度（6 缝隙）：
 * 1. division_of_labor       — 角色间任务传递
 * 2. information_flow        — 信息流方向 + 延迟
 * 3. authority_governance    — 冲突解决策略 + 决策权限使用
 * 4. trust_incentive         — 激励信号匹配度 + 信任降级触发
 * 5. knowledge_sharing       — 知识共享方向
 * 6. external_interface      — 外部接口调用审计
 *
 * @packageDocumentation
 */
import type { GapDimension, RuntimeCollaborationEvent, EvolutionSignal } from './schema-bridge';
interface DimensionCounter {
    dimension: GapDimension;
    totalEvents: number;
    modeUsed: string;
    outcomes: {
        resolved: number;
        escalated: number;
        deadlocked: number;
    };
    humanInterventions: number;
    totalDurationMs: number;
    lastEventAt: string;
}
/**
 * 记录一次运行时协作事件。
 * 由 Protocol Engine 中间件在 Agent 间消息路由时调用。
 */
export declare function recordCollaborationEvent(event: RuntimeCollaborationEvent): void;
/**
 * 采集所有维度的当前计数器快照，聚合为进化信号列表。
 * 由 M3 进化引擎定期轮询消费。
 */
export declare function collectEvolutionSignals(): EvolutionSignal[];
/** 获取指定维度的统计 */
export declare function getDimensionStats(dim: GapDimension): DimensionCounter | undefined;
/** 获取所有维度统计 */
export declare function getAllStats(): Record<string, DimensionCounter>;
/** 获取最近 N 条事件 */
export declare function getRecentEvents(n?: number): RuntimeCollaborationEvent[];
/** 重置所有计数器（用于测试） */
export declare function resetCollector(): void;
/** 获取事件总数 */
export declare function getTotalEventCount(): number;
export {};
